export function viewFor(cam, depth) {
  if (depth === undefined) return cam;
  const pivot = [115, 90];
  return {cx: pivot[0] + (cam.cx - pivot[0]) * depth, cy: pivot[1] + (cam.cy - pivot[1]) * depth, z: 1 + (cam.z - 1) * depth};
}

