  const sun = layer(() => piece(Array.from({length: 40}, (_, i) => [SUN.x + Math.cos(i / 40 * 6.283) * SUN.r, SUN.y + Math.sin(i / 40 * 6.283) * SUN.r]), {color: '#f9dd8e', lift: 0.7}));
