  const far = layer(() => piece(skylinePolygon(SKYLINE.far), {tex: news, color: '#efe2c9', edge: 'torn', lift: 0.8}));
  const building = (b, color, buildingLift, bottom = 147) => {
    const tilt = (r() - 0.5) * 0.9;
