      for (let i = 0; i < 26; i++) {
        const y = (BENCH.top + r() * BENCH.h) * U, x = (BENCH.x + r() * BENCH.w * 0.8) * U;
        ctx.strokeStyle = 'rgba(92,62,38,.4)'; ctx.lineWidth = 1 + r() * 1.5;
        ctx.beginPath(); ctx.moveTo(x, y); ctx.bezierCurveTo(x + 40, y + 2, x + 80, y - 2, x + 90 + r() * 70, y + 1); ctx.stroke();
