  });

  const clawdId = layerCount++;
  const poses = new Map();
  const pose = (action, frame) => {
    const key = `${action}:${frame}`;
    if (!poses.has(key)) {
      const canvas = makeCanvas();
      ctx = canvas.getContext('2d');
      const p = clawdParts(CLAWD.x, CLAWD.y, action, frame);
      if (action === 'walk') {
        ctx.fillStyle = 'rgba(84,62,42,.3)';
        ctx.beginPath(); ctx.ellipse((CLAWD.x + 16) * U, (CLAWD.y + 27) * U, 9 * U, 1.6 * U, 0, 0, 7); ctx.fill();
