    put(far); put(mid);
    lights(SKYLINE.mid.lights, 0, mid, 7, l => (l.warm ? C.sun : CORE));
    put(tower); put(near);
    lights(SKYLINE.near.lights, 1000, near, 10, l => (l.warm ? C.lamp : C.sun));
    put(rail); put(floor); put(benchLegs);
    put(suitcase, (s.caseX - SUITCASE.body[0]) * U);
    put(plank);
    put({canvas: pose(s.action, s.frame), id: clawdId}, (s.x - CLAWD.x) * U, (s.y - CLAWD.y) * U);
