import {jitter} from '../../會呼吸的痛/開場樣圖/v2/clip.js';
import {rng} from '../../會呼吸的痛/開場樣圖/v2/scene.js';

export const W = 1920, H = 1080;
export const UPDATES_PER_SECOND = 10;
export const LABELS = {invite: '囍', title: '嘉宾'};

export const COLORS = {
  kraft: '#c4a176', sky: '#bfd3d6', newsSky: '#eceadb', sun: '#f7e8bd', hillFar: '#c6d3cf', ground: '#eef0e6', bank: '#f7f3e8',
  pathTint: '#efe0c4', pine: '#6f8a7c', pineDark: '#5f7a6a', wall: '#f3e4c7', wallShade: '#ead8b8', roof: '#a24e3b', door: '#7c3b2c',
  gold: '#f2c14e', red: '#b8332a', petal: '#f0b7a4', cream: '#f6efe0', coat: '#2f3e52', sleeve: '#3a4b62', trousers: '#4a4a4e',
  shoe: '#3b2c24', hair: '#33281f', skin: '#e6b995', scarf: '#c99a3f', branch: '#5a4334', envelope: '#e9dcc0', ink: '#3a2f28',
};
const C = COLORS;

const piece = (pts, opts = {}) => ({kind: 'piece', pts, edge: 'cut', border: 6, lift: 1, ...opts});
const mark = (pts, color) => ({kind: 'mark', pts, color});
const stripe = (line, color, width, border = 4) => ({kind: 'stripe', line, color, width, border});
const rect = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];
const ellipse = (cx, cy, rx, ry, n = 32) => Array.from({length: n}, (_, i) => [cx + Math.cos(i / n * 2 * Math.PI) * rx, cy + Math.sin(i / n * 2 * Math.PI) * ry]);
const circle = (cx, cy, r, n = 32) => ellipse(cx, cy, r, r, n);
const arch = (x0, x1, top, base) => {
  const r = (x1 - x0) / 2, cx = x0 + r, curve = Array.from({length: 13}, (_, i) => [cx - Math.cos(i / 12 * Math.PI) * r, top + r - Math.sin(i / 12 * Math.PI) * r]);
  return [[x0, base], ...curve, [x1, base]];
};
function rotated(cx, cy, w, h, deg) {
  const a = deg * Math.PI / 180;
  const pts = [[-w / 2, -h / 2], [w / 2, -h / 2], [w / 2, h / 2], [-w / 2, h / 2]]
    .map(([x, y]) => [cx + x * Math.cos(a) - y * Math.sin(a), cy + x * Math.sin(a) + y * Math.cos(a)]);
  return {pts, frame: {cx, cy, w, h, deg}};
}

const PATH = [[1255, 652], [1240, 780], [560, 770], [640, 1060]];
export function pathCenter(t) {
  const u = 1 - t, k = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];
  const at = i => k.reduce((sum, v, j) => sum + v * PATH[j][i], 0);
  return [at(0), at(1)];
}
function pathNormal(t) {
  const [ax, ay] = pathCenter(Math.max(0, t - 0.01)), [bx, by] = pathCenter(Math.min(1, t + 0.01)), len = Math.hypot(bx - ax, by - ay);
  return [-(by - ay) / len, (bx - ax) / len];
}
const pathHalfWidth = t => 26 + 189 * t ** 1.6;
function pathOutline() {
  const side = sign => Array.from({length: 41}, (_, i) => {
    const t = i / 40, [x, y] = pathCenter(t), [nx, ny] = pathNormal(t), hw = pathHalfWidth(t) * sign;
    return [x + nx * hw, Math.min(1056, y + ny * hw)];
  });
  return [...side(1), ...side(-1).reverse()];
}

function pine(x, base, h, color) {
  const w = h * 0.4;
  return [0, 0.28, 0.54].map((k, i) => piece([[x, base - h + k * h * 0.72], [x + w * (0.55 + i * 0.25), base - h * (0.46 - k * 0.8)], [x - w * (0.55 + i * 0.25), base - h * (0.46 - k * 0.8)]], {color, border: 3, lift: 0.4}));
}
const PINES = [[120, 640, 130], [205, 650, 170], [300, 645, 120], [960, 648, 150], [1040, 652, 190], [1500, 650, 170], [1590, 655, 130], [1690, 648, 200], [1780, 650, 140]];

const footprints = Array.from({length: 7}, (_, i) => {
  const t = 0.77 + i * 0.033, [x, y] = pathCenter(t), [nx, ny] = pathNormal(t), side = i % 2 ? 20 : -20, s = 1 + (t - 0.77) * 2;
  return mark(ellipse(x + nx * side * s, y + ny * side * s, 13 * s, 7 * s, 16), 'rgba(92,68,44,.34)');
});

const FLOWER_COLORS = [C.cream, C.red, C.gold, C.petal];
const flowers = Array.from({length: 15}, (_, i) => {
  const a = Math.PI + i / 14 * Math.PI;
  return piece(circle(1255 + Math.cos(a) * 62, 612 + Math.sin(a) * 62, i % 3 ? 13 : 17, 14), {color: FLOWER_COLORS[i % 4], border: 2, lift: 0.3});
});
const chapel = [
  piece(rect(1222, 288, 66, 120), {color: C.wallShade, border: 5, name: 'tower'}),
  piece(arch(1236, 1274, 306, 366), {color: C.door, border: 2, lift: 0.2}),
  piece(arch(1245, 1265, 328, 354), {color: C.gold, border: 2, lift: 0.3, name: 'bell'}),
  piece([[1208, 292], [1255, 205], [1302, 292]], {color: C.roof, border: 5}),
  piece(rect(1120, 478, 270, 177), {color: C.wall, border: 7, lift: 1.2, name: 'wall'}),
  piece([[1096, 486], [1255, 372], [1414, 486]], {color: C.roof, border: 7, lift: 1.2, name: 'gable'}),
  piece(circle(1255, 442, 22), {color: C.gold, border: 4, lift: 0.4, name: 'rose'}),
  piece(arch(1148, 1188, 515, 610), {color: C.gold, border: 3, lift: 0.3, name: 'window'}),
  piece(arch(1322, 1362, 515, 610), {color: C.gold, border: 3, lift: 0.3}),
  piece(arch(1224, 1286, 572, 655), {color: C.door, border: 4, lift: 0.5, name: 'door'}),
  stripe([[1255, 590], [1255, 652]], C.gold, 2, 0),
  ...flowers,
];

function bunting(from, to, sag) {
  const point = t => [from[0] + (to[0] - from[0]) * t, from[1] + (to[1] - from[1]) * t + Math.sin(t * Math.PI) * sag];
  const line = Array.from({length: 17}, (_, i) => point(i / 16));
  const count = Math.round(Math.hypot(to[0] - from[0], to[1] - from[1]) / 40);
  const flags = Array.from({length: count}, (_, i) => {
    const [x, y] = point((i + 0.5) / count);
    return piece([[x - 13, y], [x + 13, y], [x, y + 30]], {color: [C.red, C.gold, C.cream][i % 3], border: 2, lift: 0.3});
  });
  return [stripe([[to[0], to[1] - 4], [to[0], 650]], C.branch, 6, 2), stripe(line, C.ink, 2, 0), ...flags];
}

const FEET = pathCenter(0.7);
const fig = pts => pts.map(([x, y]) => [FEET[0] + x, FEET[1] + y]);
const figCircle = (x, y, r) => circle(FEET[0] + x, FEET[1] + y, r, 24);
const figure = [
  piece(fig(rect(-30, -90, 26, 78)), {color: C.trousers, border: 4, lift: 0.5}),
  piece(fig(rect(4, -90, 26, 78)), {color: C.trousers, border: 4, lift: 0.5}),
  piece(fig(rect(-36, -16, 34, 16)), {color: C.shoe, border: 3, lift: 0.3}),
  piece(fig(rect(2, -16, 34, 16)), {color: C.shoe, border: 3, lift: 0.3}),
  stripe(fig([[-50, -196], [-66, -110]]), C.sleeve, 26, 5),
  stripe(fig([[50, -196], [66, -110]]), C.sleeve, 26, 5),
  piece(fig([[-30, -212], [30, -212], [48, -200], [54, -180], [60, -82], [-60, -82], [-54, -180], [-48, -200]]), {color: C.coat, border: 6, lift: 1.3, name: 'coat'}),
  stripe(fig([[0, -196], [0, -86]]), C.sleeve, 3, 0),
  piece(figCircle(-33, -250, 7), {color: C.skin, border: 3, lift: 0.2}),
  piece(figCircle(33, -250, 7), {color: C.skin, border: 3, lift: 0.2}),
  piece(figCircle(0, -250, 33), {color: C.hair, border: 5, lift: 0.8, name: 'hair'}),
  piece(fig(rect(-32, -228, 64, 28)), {color: C.scarf, border: 4, lift: 0.6}),
  piece(fig(rect(-26, -204, 22, 66)), {color: C.scarf, border: 4, lift: 0.5}),
  piece(figCircle(-67, -100, 11), {color: C.skin, border: 3, lift: 0.3}),
  piece(rotated(FEET[0] + 88, FEET[1] - 92, 48, 34, -14).pts, {color: C.red, border: 4, lift: 0.7, name: 'heldInvite'}),
  piece(figCircle(67, -100, 11), {color: C.skin, border: 3, lift: 0.3}),
];

const BRANCHES = [
  [[34, 172], [210, 150], [400, 190], [560, 170]],
  [[210, 150], [290, 90], [360, 62]],
  [[400, 190], [470, 262]],
  [[100, 162], [132, 240]],
  [[290, 90], [262, 44]],
];
const branch = [
  ...BRANCHES.map((line, i) => stripe(line, C.branch, i ? 9 : 15, 5)),
  ...[[120, 158, 40, 11], [280, 158, 56, 12], [448, 172, 44, 10], [322, 70, 30, 9]].map(([x, y, rx, ry]) => piece(ellipse(x, y, rx, ry, 18), {color: C.bank, edge: 'torn', lift: 0.3})),
];

const envelope = rotated(1625, 880, 400, 270, 5);
const invite = rotated(1600, 860, 390, 262, -4);
const tape = rotated(1480, 738, 120, 38, -28);
const placeCard = rotated(1400, 975, 250, 104, 5);
const cardLayer = [
  piece(envelope.pts, {color: C.envelope, lift: 1.3}),
  piece(invite.pts, {color: C.red, lift: 1.8, border: 8, detail: 'invite', frame: invite.frame, name: 'invite'}),
  mark(tape.pts, 'rgba(226,206,160,.84)'),
  piece(placeCard.pts, {color: C.cream, lift: 1.6, border: 6, detail: 'title', frame: placeCard.frame, name: 'placeCard'}),
];

export const LAYERS = [
  {id: 'sky', pieces: [
    piece([[32, 250], [420, 235], [1000, 262], [1500, 228], [1888, 250], [1888, 680], [32, 680]], {tex: 'news', color: C.newsSky, edge: 'torn', lift: 0.6, name: 'news'}),
    piece([[30, 28], [1890, 24], [1886, 330], [1400, 300], [800, 345], [320, 310], [34, 340]], {color: C.sky, edge: 'torn', lift: 0.9, name: 'top'}),
  ]},
  {id: 'sun', pieces: [piece(circle(1590, 232, 118, 44), {color: C.sun, border: 8, lift: 0.7})]},
  {id: 'hills', pieces: [piece([[30, 600], [250, 520], [520, 575], [820, 505], [1120, 560], [1430, 500], [1700, 560], [1890, 520], [1890, 700], [30, 700]], {tex: 'news', color: C.hillFar, edge: 'torn', lift: 0.8})]},
  {id: 'pines', pieces: PINES.flatMap(([x, base, h], i) => pine(x, base, h, i % 2 ? C.pineDark : C.pine))},
  {id: 'ground', pieces: [piece([[30, 628], [400, 612], [800, 640], [1250, 628], [1600, 640], [1890, 618], [1890, 1054], [30, 1052]], {color: C.ground, edge: 'torn', lift: 1.2})]},
  {id: 'path', pieces: [piece(pathOutline(), {tex: 'kraft', color: C.pathTint, edge: 'torn', lift: 0.5})]},
  {id: 'footprints', pieces: footprints},
  {id: 'chapel', pieces: chapel},
  {id: 'bunting', pieces: [...bunting([1226, 372], [990, 520], 34), ...bunting([1284, 372], [1500, 505], 30)]},
  {id: 'figureShadow', pieces: [mark([[FEET[0] - 34, FEET[1] - 4], [FEET[0] + 34, FEET[1] - 2], [FEET[0] - 240, FEET[1] + 70], [FEET[0] - 330, FEET[1] + 42]], 'rgba(60,70,84,.24)')]},
  {id: 'figure', pieces: figure},
  {id: 'bank', pieces: [piece([[30, 1056], [30, 960], [170, 925], [360, 960], [560, 1000], [900, 1020], [1180, 1030], [1500, 1015], [1890, 985], [1890, 1056]], {color: C.bank, edge: 'torn', lift: 1.6})]},
  {id: 'clipping', pieces: [piece(rotated(1560, 890, 560, 310, -3).pts, {tex: 'news', color: '#efe6cf', edge: 'torn', lift: 1.1})]},
  {id: 'branch', pieces: branch},
];

export const findLayer = id => {
  const layer = LAYERS.find(l => l.id === id);
  if (!layer) throw new Error(`未知图层：${id}`);
  return layer;
};

export function pieceBounds(p) {
  const pts = p.kind === 'stripe' ? p.line : p.pts, pad = p.kind === 'stripe' ? (p.width + p.border) / 2 : 0;
  const xs = pts.map(q => q[0]), ys = pts.map(q => q[1]);
  return {x0: Math.min(...xs) - pad, y0: Math.min(...ys) - pad, x1: Math.max(...xs) + pad, y1: Math.max(...ys) + pad};
}
export function layerBounds(layer) {
  const all = layer.pieces.map(pieceBounds);
  return {x0: Math.min(...all.map(b => b.x0)), y0: Math.min(...all.map(b => b.y0)), x1: Math.max(...all.map(b => b.x1)), y1: Math.max(...all.map(b => b.y1))};
}
export const overlaps = (a, b) => a.x0 < b.x1 && b.x0 < a.x1 && a.y0 < b.y1 && b.y0 < a.y1;

// 喜宴的红金纸屑从礼堂一侧飘出，越往人物方向越只剩雪片。
function flakes() {
  const r = rng(2026), out = [];
  const blocks = [layerBounds(findLayer('figure')), layerBounds({pieces: cardLayer}), pieceBounds(chapel.find(p => p.name === 'door'))]
    .map(b => ({x0: b.x0 - 12, y0: b.y0 - 12, x1: b.x1 + 12, y1: b.y1 + 12}));
  const scatter = (count, zone, color) => {
    let placed = 0;
    while (placed < count) {
      const x = zone.x0 + r() * (zone.x1 - zone.x0), y = zone.y0 + r() * (zone.y1 - zone.y0), size = 4 + r() * 6;
      const shape = ellipse(x, y, size, size * (0.65 + r() * 0.35), 9);
      if (blocks.some(b => overlaps(pieceBounds({kind: 'piece', pts: shape}), b))) continue;
      out.push(piece(shape, {color: color(r()), edge: 'cut', border: 2, lift: 0.3}));
      placed++;
    }
  };
  scatter(14, {x0: 980, y0: 400, x1: 1530, y1: 700}, k => (k < 0.55 ? C.red : C.gold));
  scatter(44, {x0: 70, y0: 70, x1: 1850, y1: 960}, () => C.cream);
  return out;
}
LAYERS.push({id: 'flakes', pieces: flakes()}, {id: 'card', pieces: cardLayer});

export function layerOffset(id, tick) {
  const index = LAYERS.indexOf(findLayer(id));
  return jitter(index + 1, tick);
}

import {rng} from '../../會呼吸的痛/開場樣圖/v2/scene.js';
import {roughen, hashId} from '../../會呼吸的痛/MV/sheet.js';
import {W, H, UPDATES_PER_SECOND, LAYERS, LABELS, COLORS as C, layerOffset} from './scene.js';

const CORE = '#fbf5e6';
const FONT = '"Songti SC"';

function makeCanvas(w = W, h = H) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
}
function makeTexture(paint, w = W, h = H) {
  const c = makeCanvas(w, h);
  paint(c.getContext('2d'), w, h);
  return c;
}

export function createPaper() {
  const r = rng(1026);
  const fibre = makeTexture((t, w, h) => {
    t.fillStyle = '#fff'; t.fillRect(0, 0, w, h);
    for (let i = 0; i < 9000; i++) {
      const x = r() * w, y = r() * h, a = r() * 6.3, l = 3 + r() * 14;
      t.strokeStyle = r() < 0.72 ? `rgba(90,70,45,${0.05 + r() * 0.12})` : 'rgba(255,255,255,.5)';
      t.lineWidth = 0.4 + r() * 0.7;
      t.beginPath(); t.moveTo(x, y); t.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); t.stroke();
    }
  });
  const kraft = makeTexture((t, w, h) => {
    t.fillStyle = C.kraft; t.fillRect(0, 0, w, h);
    for (let i = 0; i < 30000; i++) {
      const x = r() * w, y = r() * h, l = 4 + r() * 13, a = (r() - 0.5) * 1.6;
      t.strokeStyle = r() < 0.55 ? `rgba(95,66,36,${0.06 + r() * 0.16})` : `rgba(240,215,175,${0.08 + r() * 0.18})`;
      t.lineWidth = 0.4 + r() * 0.8;
      t.beginPath(); t.moveTo(x, y); t.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); t.stroke();
    }
  });
  // 旧报纸只用假字条和半调网点，不出现可读文字。
  const news = makeTexture((t, w, h) => {
    t.fillStyle = '#eadfc8'; t.fillRect(0, 0, w, h);
    const cols = 6, cw = w / cols;
    for (let c = 0; c < cols; c++) {
      const x = c * cw + 10;
      for (let y = 8; y < h; y += 9) {
        if (c === 2 && y > 180 && y < 320) continue;
        let px = x;
        const end = x + cw - 20;
        while (px < end) {
          const len = 3 + r() * 13;
          t.fillStyle = `rgba(62,56,48,${0.2 + r() * 0.2})`;
          t.fillRect(px, y, Math.min(len, end - px), 3);
          px += len + 2.5;
        }
      }
    }
    t.fillStyle = 'rgba(62,56,48,.3)';
    for (let y = 184; y < 316; y += 5) for (let x = 2 * cw + 12; x < 3 * cw - 12; x += 5) {
      t.beginPath(); t.arc(x, y, 0.8 + 1.5 * Math.abs(Math.sin(x / 26 + y / 40)), 0, 7); t.fill();
    }
  }, 1080, 720);
  const TEXTURES = {news, kraft};

  let ctx;
  const trace = pts => { ctx.beginPath(); pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y))); ctx.closePath(); };
  const overlayFibre = () => {
    ctx.globalCompositeOperation = 'multiply';
    ctx.fillStyle = ctx.createPattern(fibre, 'repeat');
    ctx.fillRect(0, 0, W, H);
    ctx.globalCompositeOperation = 'source-over';
  };
  const DETAILS = {
    invite({w, h}) {
      ctx.strokeStyle = C.gold; ctx.lineWidth = 4;
      ctx.strokeRect(-w / 2 + 20, -h / 2 + 20, w - 40, h - 40);
      ctx.fillStyle = C.gold; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.font = `700 150px ${FONT}`;
      ctx.fillText(LABELS.invite, 0, 4);
    },
    title() {
      ctx.fillStyle = C.ink; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.font = `700 64px ${FONT}`;
      ctx.letterSpacing = '12px';
      ctx.fillText(LABELS.title, 6, 2);
      ctx.letterSpacing = '0px';
    },
  };

  function paintPiece(p, seed) {
    const torn = p.edge === 'torn';
    const outer = torn ? roughen(p.pts, {step: 7, amp: 7, seed}) : roughen(p.pts, {step: 34, amp: 0.8, seed});
    const inner = torn ? roughen(p.pts, {step: 7, amp: 3.5, seed: seed + 17}) : outer;
    ctx.save();
    ctx.shadowColor = 'rgba(58,42,24,.42)'; ctx.shadowBlur = 7 + p.lift * 7; ctx.shadowOffsetX = 2 + p.lift * 2; ctx.shadowOffsetY = 3 + p.lift * 4;
    trace(outer);
    ctx.fillStyle = CORE; ctx.fill();
    if (!torn) { ctx.strokeStyle = CORE; ctx.lineWidth = p.border; ctx.lineJoin = 'round'; ctx.stroke(); }
    ctx.restore();
    ctx.save();
    trace(inner); ctx.clip();
    if (p.tex) {
      ctx.fillStyle = ctx.createPattern(TEXTURES[p.tex], 'repeat'); ctx.fillRect(0, 0, W, H);
      ctx.globalCompositeOperation = 'multiply';
    }
    ctx.fillStyle = p.color; ctx.fillRect(0, 0, W, H);
    ctx.globalCompositeOperation = 'source-over';
    overlayFibre();
    if (p.detail) {
      const {cx, cy, deg} = p.frame;
      ctx.translate(cx, cy); ctx.rotate(deg * Math.PI / 180);
      DETAILS[p.detail](p.frame);
    }
    ctx.restore();
  }
  function paintStripe(p) {
    const path = () => { ctx.beginPath(); p.line.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y))); };
    ctx.save();
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    if (p.border) {
      ctx.shadowColor = 'rgba(58,42,24,.4)'; ctx.shadowBlur = 7; ctx.shadowOffsetX = 2; ctx.shadowOffsetY = 4;
      path(); ctx.strokeStyle = CORE; ctx.lineWidth = p.width + p.border; ctx.stroke();
      ctx.shadowColor = 'transparent';
    }
    path(); ctx.strokeStyle = p.color; ctx.lineWidth = p.width; ctx.stroke();
    ctx.restore();
  }
  function paintMark(p) {
    trace(p.pts);
    ctx.fillStyle = p.color; ctx.fill();
  }

  const layers = LAYERS.map(layer => {
    const canvas = makeCanvas();
    ctx = canvas.getContext('2d');
    layer.pieces.forEach((p, i) => {
      if (p.kind === 'stripe') paintStripe(p);
      else if (p.kind === 'mark') paintMark(p);
      else paintPiece(p, hashId(`${layer.id}:${i}`));
    });
    return {id: layer.id, canvas};
  });

  const canvas = makeCanvas();
  document.body.append(canvas);
  const out = canvas.getContext('2d');

  // tick 为 null 时输出静态样图；底层牛皮纸不动，其余各层独立抖动。
  function render(tick = null) {
    out.fillStyle = out.createPattern(kraft, 'no-repeat');
    out.fillRect(0, 0, W, H);
    for (const layer of layers) {
      const {dx, dy} = tick === null ? {dx: 0, dy: 0} : layerOffset(layer.id, tick);
      out.drawImage(layer.canvas, dx, dy);
    }
  }
  function play() {
    let tick = 0;
    return setInterval(() => render(tick++), 1000 / UPDATES_PER_SECOND);
  }
  return {canvas, render, play};
}

// 在页面内运行的数值检查：不查看图片，只读取画布像素。
const hex = s => [1, 3, 5].map(i => parseInt(s.slice(i, i + 2), 16));

function mean(d, width, x, y, size = 5) {
  const sum = [0, 0, 0];
  for (let j = -size; j <= size; j++) for (let i = -size; i <= size; i++) {
    const k = ((y + j) * width + x + i) * 4;
    for (let c = 0; c < 3; c++) sum[c] += d[k + c];
  }
  return sum.map(v => v / (2 * size + 1) ** 2);
}
const distance = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);

function hsv([r, g, b]) {
  const max = Math.max(r, g, b), min = Math.min(r, g, b), delta = max - min;
  let h = 0;
  if (delta) h = max === r ? ((g - b) / delta + 6) % 6 : max === g ? (b - r) / delta + 2 : (r - g) / delta + 4;
  return {h: h * 60, s: max ? delta / max : 0, v: max / 255};
}

// 中心点取实际几何，颜色误差上限 60：纸纤维正片叠底后会比色标略暗。
export function colorProbes(ctx, findLayer, C) {
  const {width, data} = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height);
  const center = (layer, name) => {
    const {pts} = findLayer(layer).pieces.find(p => p.name === name);
    return pts.reduce((s, p) => [s[0] + p[0] / pts.length, s[1] + p[1] / pts.length], [0, 0]).map(Math.round);
  };
  const [hx, hy] = center('figure', 'hair'), [cx, cy] = center('figure', 'coat'), [hix, hiy] = center('figure', 'heldInvite');
  const [wx, wy] = center('chapel', 'window'), [rx, ry] = center('chapel', 'rose');
  const list = [
    ['牛皮纸外框', 12, 12, C.kraft], ['牛皮纸下框', 960, 1072, C.kraft], ['天空', 800, 120, C.sky], ['太阳', 1590, 232, C.sun],
    ['头发', hx, hy, C.hair], ['外套（背缝一侧）', cx + 25, cy, C.coat], ['手中喜帖', hix, hiy, C.red],
    ['礼堂窗', wx, wy, C.gold], ['玫瑰窗', rx, ry, C.gold], ['喜帖红底', 1450, 800, C.red], ['席卡留白', 1305, 960, C.cream],
    ['雪地空白', 1000, 760, C.ground],
  ];
  return list.map(([name, x, y, want]) => {
    const got = mean(data, width, x, y, 4), d = distance(got, hex(want));
    return {name, x, y, want, got: got.map(Math.round), distance: Math.round(d), pass: d < 60};
  });
}

export function paletteStats(ctx) {
  const {data} = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height), n = data.length / 4;
  let opaque = true, luma = 0, dark = 0, purple = 0, neon = 0, red = 0;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] !== 255) opaque = false;
    const l = 0.2126 * data[i] + 0.7152 * data[i + 1] + 0.0722 * data[i + 2], c = hsv([data[i], data[i + 1], data[i + 2]]);
    luma += l;
    if (l < 60) dark++;
    if (c.h >= 255 && c.h <= 325 && c.s > 0.2) purple++;
    if (c.s > 0.9 && c.v > 0.9) neon++;
    if ((c.h < 12 || c.h > 350) && c.s > 0.55 && c.v > 0.45 && c.v < 0.85) red++;
  }
  const pct = v => +(v / n * 100).toFixed(3);
  return {width: ctx.canvas.width, height: ctx.canvas.height, opaque, meanLuma: +(luma / n).toFixed(1), darkPct: pct(dark), purplePct: pct(purple), neonPct: pct(neon), redPct: pct(red)};
}

// 从喜帖下边缘向外走，应依次出现红纸、白边、比信封更暗的投影。
export function edgeProfile(ctx, frame) {
  const a = frame.deg * Math.PI / 180, {width, data} = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height);
  return Array.from({length: 26}, (_, i) => {
    const local = frame.h / 2 - 6 + i * 2, x = Math.round(frame.cx - local * Math.sin(a) + 40 * Math.cos(a)), y = Math.round(frame.cy + local * Math.cos(a) + 40 * Math.sin(a));
    return mean(data, width, x, y, 0).map(Math.round);
  });
}

// 比较席卡内墨色像素，确认文字真的绘制且没有超出卡片。
export function inkInCard(ctx, frame, ink) {
  const {width, height, data} = ctx.getImageData(0, 0, ctx.canvas.width, ctx.canvas.height), a = frame.deg * Math.PI / 180, want = hex(ink);
  let inside = 0, minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
  for (let v = -frame.h / 2 - 20; v < frame.h / 2 + 20; v++) for (let u = -frame.w / 2 - 20; u < frame.w / 2 + 20; u++) {
    const x = Math.round(frame.cx + u * Math.cos(a) - v * Math.sin(a)), y = Math.round(frame.cy + u * Math.sin(a) + v * Math.cos(a));
    if (x < 0 || y < 0 || x >= width || y >= height) continue;
    const k = (y * width + x) * 4;
    if (distance([data[k], data[k + 1], data[k + 2]], want) > 40) continue;
    inside++; minX = Math.min(minX, u); maxX = Math.max(maxX, u); minY = Math.min(minY, v); maxY = Math.max(maxY, v);
  }
  return {inside, minX, maxX, minY, maxY};
}

// 系统没有该字体时 Canvas 会回退，字形像素与无衬线版本相同。
export function fontResolved(sample, font, size = 80) {
  const shot = family => {
    const c = document.createElement('canvas'); c.width = c.height = 200;
    const t = c.getContext('2d', {willReadFrequently: true});
    t.font = `700 ${size}px ${family}`; t.textBaseline = 'top'; t.fillText(sample, 10, 10);
    return t.getImageData(0, 0, 200, 200).data;
  };
  const a = shot(font), b = shot('sans-serif');
  let diff = 0, ink = 0;
  for (let i = 3; i < a.length; i += 4) { if (a[i] > 128) ink++; if (Math.abs(a[i] - b[i]) > 64) diff++; }
  return {ink, diff, resolved: ink > 200 && diff > 100};
}

// 在喜帖内部搜索最佳位移，确认画面真的按图层偏移量移动。
export function measuredShift(ctx, baseline, box) {
  const now = ctx.getImageData(box.x, box.y, box.w, box.h).data;
  const grab = (x, y) => baseline.getImageData(box.x + x, box.y + y, box.w, box.h).data;
  let best = {sad: Infinity};
  for (let dy = -3; dy <= 3; dy++) for (let dx = -3; dx <= 3; dx++) {
    const was = grab(-dx, -dy);
    let sad = 0;
    for (let i = 0; i < now.length; i += 4) sad += Math.abs(now[i] - was[i]);
    if (sad < best.sad) best = {dx, dy, sad};
  }
  return best;
}

